struct Adder {
    static constexpr int op(int a, int b) { return a + b; }
};
struct Multiplier {
    static constexpr int op(int a, int b) { return a * b; }
};

template <typename Strategy>
constexpr int dispatch(int x, int y) {
    return Strategy::op(x, y);
}

// Compile-time specialization and dispatch:
constexpr int sum = dispatch<Adder>(20, 3);    // 23
constexpr int prod = dispatch<Multiplier>(20, 3); // 60
// No vtable overhead. Specific code generated for each call site.
